// Shared, editable paper definitions -> dependency-free native and browser constants.
// Run with Node from any directory. Generated files are committed for normal builds.
const fs=require('fs'),path=require('path'),{meta,icons,templates}=JSON.parse(fs.readFileSync(path.join(__dirname,'papers.json'),'utf8'));
const q=JSON.stringify,f=n=>Number.isInteger(n)?n+'f':n+'f',arr=a=>'new float[]{'+a.map(f).join(',')+'}',matrix=a=>'new float[][]{'+a.map(arr).join(',')+'}';
let java='package br.com.folha.notes;\nimport java.util.*;\n/** Generated by generate-papers.cjs from papers.json; no runtime parsing. */\nfinal class StudyPaper {\n static final class Label {final String text;final float x,y,size;Label(String t,float X,float Y,float s){text=t;x=X;y=Y;size=s;}}\n static final class Guide {final String text;final float x,y,size;final boolean trace;Guide(String t,float X,float Y,float s,boolean g){text=t;x=X;y=Y;size=s;trace=g;}}\n static final String[] IDS={'+meta.filter(m=>m.id!=='pdf').map(m=>q(m.id)).join(',')+'};\n static final String[] NAMES={'+meta.filter(m=>m.id!=='pdf').map(m=>q(m.name)).join(',')+'};\n static final Map<String,float[][]> LINES=new HashMap<>(),CELLS=new HashMap<>(),ICONS=new HashMap<>();\n static final Map<String,Label[]> LABELS=new HashMap<>();\n static final Map<String,Guide[]> GUIDES=new HashMap<>();\n';
let count=0;for(const [id,t]of Object.entries(templates)){java+=' static void init'+count+++'(){\n LINES.put('+q(id)+','+matrix(t.lines)+');\n CELLS.put('+q(id)+','+matrix(t.cells)+');\n LABELS.put('+q(id)+',new Label[]{'+t.labels.filter(l=>l.text).map(l=>'new Label('+q(l.text)+','+[l.x,l.y,l.size].map(f).join(',')+')').join(',')+'});\n GUIDES.put('+q(id)+',new Guide[]{'+(t.glyphs||[]).map(g=>'new Guide('+q(g.text)+','+[g.x,g.y,g.size].map(f).join(',')+','+g.trace+')').join(',')+'});\n }\n';}
java+=' static {\n'+Array.from({length:count},(_,i)=>' init'+i+'();').join('\n')+'\n';
for(const [id,paths]of Object.entries(icons))java+=' ICONS.put('+q(id)+','+matrix(paths)+');\n';
java+=' }\n static String name(String id){switch(id){'+meta.map(m=>'case '+q(m.id)+':return '+q(m.name)+';').join('')+'default:return "Caderno";}}\n static String hint(String id){switch(id){'+meta.map(m=>'case '+q(m.id)+':return '+q(m.hint)+';').join('')+'default:return "";}}\n static int color(String id){switch(id){'+meta.map(m=>'case '+q(m.id)+':return 0xFF'+m.color.slice(1).toUpperCase()+';').join('')+'default:return 0xFF487763;}}\n static float[][] icon(String id){String key;switch(id){'+meta.map(m=>'case '+q(m.id)+':key='+q(m.icon)+';break;').join('')+'default:key="blank";}return ICONS.get(key);}\n static float[] cell(String id,float x,float y){float[][] cells=CELLS.get(id);if(cells==null)return null;for(float[] c:cells){int col=(int)Math.floor((x-c[0])/c[2]),row=(int)Math.floor((y-c[1])/c[2]);if(col>=0&&col<c[3]&&row>=0&&row<c[4]){float l=c[0]+col*c[2],t=c[1]+row*c[2];return new float[]{l,t,l+c[2],t+c[2]};}}return null;}\n}\n';
fs.writeFileSync(path.join(__dirname,'src/br/com/folha/notes/StudyPaper.java'),java);
const desktop=fs.existsSync(path.join(__dirname,'desktop/web'))?'desktop/web':'../desktop/web';
fs.writeFileSync(path.join(__dirname,desktop,'paper-data.mjs'),'// Generated by generate-papers.cjs from papers.json.\nexport const paperData='+JSON.stringify({meta,icons,templates})+';\n');
const kana=JSON.parse(fs.readFileSync(path.join(__dirname,'kana-glyphs.json'),'utf8'));
fs.writeFileSync(path.join(__dirname,desktop,'kana-glyphs.mjs'),'// Klee Project Authors; SIL OFL 1.1. See licenses/klee-one.txt.\nexport const kanaGlyphs='+JSON.stringify(kana.glyphs)+';\n');
let glyphJava='package br.com.folha.notes;\nimport java.util.*;\n/** Kana subset derived from Klee One; Copyright 2020 Klee Project Authors; SIL OFL 1.1. */\nfinal class KanaGlyphs {static final Map<String,String> DATA=new HashMap<>();static {\n';
for(const [ch,contour]of Object.entries(kana.glyphs))glyphJava+='DATA.put('+q(ch)+','+q(contour)+');\n';glyphJava+='}}\n';fs.writeFileSync(path.join(__dirname,'src/br/com/folha/notes/KanaGlyphs.java'),glyphJava);
console.log(meta.length-1+' paper types, '+Object.keys(templates).length+' study templates generated.');
